#!/bin/bash
set -e
cd avbox

echo "=== 写入音乐 UI ==="

echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxMusicTheme.kt
echo "LxMusicTheme.kt 已写入"

echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxSourceSettings.kt
echo "LxSourceSettings.kt 已写入（URL + 本地文件）"


echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxLyricSettingsActivity.kt
echo "LxLyricSettingsActivity.kt 已写入"
echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxQualitySettingsActivity.kt
echo "LxQualitySettingsActivity.kt 已写入"
echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxPlaybackSettingsActivity.kt
echo "LxPlaybackSettingsActivity.kt 已写入"
echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/ui/activity/LxFavoritesActivity.kt
echo "LxFavoritesActivity.kt 已写入"

python3 << 'PYEOF2'
with open("app/src/main/AndroidManifest.xml", "r", encoding="utf-8") as f:
    content = f.read()
activities = [(".ui.activity.LxSourceSettingsActivity", "音乐源管理"),(".ui.activity.LxMusicSearchActivity", "音乐解析"),(".ui.activity.LxLyricSettingsActivity", "歌词设置"),(".ui.activity.LxQualitySettingsActivity", "音质选择"),(".ui.activity.LxFavoritesActivity", "我的喜欢"),(".ui.activity.LxPlaybackSettingsActivity", "播放设置"),]
for activity_name, label in activities:
    if activity_name not in content:
        insert = f'        <activity android:name="{activity_name}" android:label="{label}" android:exported="false" />\n'
        content = content.replace("</application>", insert + "    </application>")
with open("app/src/main/AndroidManifest.xml", "w", encoding="utf-8") as f:
    f.write(content)
PYEOF2
echo "=== 完成 ==="